import{_ as t,o,c as s,a2 as r}from"./chunks/framework.CqdVOxXJ.js";const c=JSON.parse(`{"title":"3. Get the customer's OK","description":"","frontmatter":{},"headers":[],"relativePath":"desk/job/03-customer-approval.md","filePath":"desk/job/03-customer-approval.md","lastUpdated":1794621279000}`),n={name:"desk/job/03-customer-approval.md"};function a(i,e,h,l,p,d){return o(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="_3-get-the-customer-s-ok" tabindex="-1">3. Get the customer&#39;s OK <a class="header-anchor" href="#_3-get-the-customer-s-ok" aria-label="Permalink to &quot;3. Get the customer&#39;s OK&quot;">​</a></h1><p><strong>Who:</strong> Owner or admin · <strong>Where:</strong> Work tab › <strong>Quote</strong> card, and the <strong>Pay</strong> tab</p><p>The customer approves the estimate on their own phone. You may also take a deposit before work starts.</p><h2 id="send-the-estimate" tabindex="-1">Send the estimate <a class="header-anchor" href="#send-the-estimate" aria-label="Permalink to &quot;Send the estimate&quot;">​</a></h2><ol><li>On the <strong>Quote</strong> card, press <strong>Email quote</strong>, or use <strong>More ▾ › Copy customer link</strong> and send the link by SMS or Messenger.</li><li>The customer opens the link on the Customer Portal. They see the job, the car and the total.</li><li>They press <strong>Approve estimate</strong> or <strong>Decline estimate</strong>. No money is taken.</li><li>You&#39;ll see it on the job&#39;s next-step button and in <strong>Workshop › Customer activity</strong>.</li></ol><p>If the customer agrees in person or by phone, just carry on to the next step.</p><div class="info custom-block"><p class="custom-block-title">Declined?</p><p>Change the work lines and save the quote again, or cancel the job from <strong>More ▾ › Cancel job</strong> (a reason is required).</p></div><h2 id="take-the-deposit-if-your-shop-needs-one" tabindex="-1">Take the deposit (if your shop needs one) <a class="header-anchor" href="#take-the-deposit-if-your-shop-needs-one" aria-label="Permalink to &quot;Take the deposit (if your shop needs one)&quot;">​</a></h2><p>Private jobs default to a <strong>50%</strong> deposit. Your shop decides whether the deposit blocks anything: nothing, the start of work, or release. The <strong>Pay</strong> tab says which in plain words.</p><ol><li>Open the <strong>Pay</strong> tab.</li><li>Under <strong>Record a payment</strong>, set <strong>Who paid</strong>: Customer, the <strong>Amount</strong>, and the <strong>Method</strong> (Cash, GCash, Maya, Bank transfer, Card or Other).</li><li>For a bank transfer, choose the <strong>Bank account</strong> and fill in <strong>Reference</strong>.</li><li>Press <strong>Record payment</strong> and confirm.</li><li>Print an acknowledgement from <strong>Work › Job order › More papers › Payment acknowledgement</strong>.</li></ol><p>The <strong>Summary</strong> card shows <strong>Deposit still due</strong> until it&#39;s covered.</p><div class="tip custom-block"><p class="custom-block-title">Different deposit for this job?</p><p>Open <strong>Job money settings › Down payment</strong> on the Pay tab, press <strong>Change the down payment</strong>, enter a percent or amount with a reason, and press <strong>Save down payment</strong>.</p></div><p><strong>Next:</strong> <a href="/rakkii-cars-guide/desk/job/04-start-work">4. Assign and start work</a></p>',13)])])}const m=t(n,[["render",a]]);export{c as __pageData,m as default};
